def transform(grid):
    h, w = len(grid), len(grid[0])
    # In the bottom row, cells left of the diagonal follow the underlying sequence.
    seq = [grid[h - 1][c] for c in range(min(w, h - 1))]
    p = len(seq)
    for period in range(1, len(seq) + 1):
        if all(seq[i] == seq[i % period] for i in range(len(seq))):
            p = period
            break

    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if out[r][c] == 0:
                idx = c if c < r else c - 1
                out[r][c] = seq[idx % p]
    return out
